package os.aios.core;
import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import android.media.MediaMetadataRetriever;import android.net.Uri;import java.io.*;import java.nio.charset.StandardCharsets;import org.json.*;
/** Durable, version-aware context processing registry and intent ledger. */
final class ContextProcessingService extends SQLiteOpenHelper{
 private final Context context;ContextProcessingService(Context c){super(c,"aios_processing.db",null,1);context=c.getApplicationContext();setWriteAheadLoggingEnabled(true);}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE intents(id TEXT PRIMARY KEY,resource_uri TEXT NOT NULL,resource_version TEXT NOT NULL,operator TEXT NOT NULL,processor_version TEXT NOT NULL,state TEXT NOT NULL,authorization_id TEXT NOT NULL,result TEXT NOT NULL DEFAULT '{}',error TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(resource_uri,resource_version,operator,processor_version))");}public void onUpgrade(SQLiteDatabase d,int a,int b){}
 synchronized JSONObject call(String action,JSONObject p)throws Exception{if(action.equals("capabilities"))return capabilities();if(action.equals("get"))return row(p.getString("id"));if(action.equals("submit"))return submit(p);if(action.equals("invalidate")){getWritableDatabase().execSQL("UPDATE intents SET state='cancelled',updated_at=? WHERE resource_uri=? AND resource_version<>? AND state NOT IN ('cancelled','failed')",new Object[]{System.currentTimeMillis(),p.getString("resource_uri"),p.getString("resource_version")});return new JSONObject().put("invalidated",true);}throw new IllegalArgumentException("Unknown processing action");}
 private JSONObject capabilities()throws Exception{JSONArray a=new JSONArray();a.put(cap("text.extract",true,"UTF-8 text resources"));a.put(cap("video.metadata",true,"duration and dimensions"));a.put(cap("video.frames",false,"frame extraction requires FD result worker"));a.put(cap("audio.asr",false,"speech adapter has no general resource transcription IPC"));a.put(cap("image.ocr",false,"no verified on-device OCR engine installed"));a.put(cap("image.face.detect",false,"sensitive processor requires explicit enrollment and implementation"));a.put(cap("image.face.recognize",false,"no enrolled face profile"));JSONObject documents=CoreCapabilities.feature(context,"documents");a.put(cap("document.parse",documents.getString("state").equals("ready"),documents.getString("reason_code")).put("availability",documents));return new JSONObject().put("items",a);}
 private JSONObject cap(String id,boolean available,String reason)throws Exception{return new JSONObject().put("id",id).put("version",1).put("available",available).put("reason",reason);}
 private JSONObject submit(JSONObject p)throws Exception{String op=p.getString("operator"),uri=p.getString("resource_uri"),version=p.getString("resource_version"),authorization=p.getString("authorization_id");CoreState.automation().call("authorization.require",new JSONObject().put("id",authorization).put("capability","context.process").put("resource",uri).put("plan_version",p.optLong("plan_version",1)));String processorVersion=op+":1",id=os.aios.runtime.CoreContracts.stableId("processing",uri,version,processorVersion);JSONObject old=find(id);if(old!=null)return old.put("existing",true);long now=System.currentTimeMillis();getWritableDatabase().execSQL("INSERT INTO intents VALUES(?,?,?,?,?,'running',?,'{}','',?,?)",new Object[]{id,uri,version,op,processorVersion,authorization,now,now});try{JSONObject result=execute(op,Uri.parse(uri),p);getWritableDatabase().execSQL("UPDATE intents SET state='succeeded',result=?,updated_at=? WHERE id=?",new Object[]{result.toString(),System.currentTimeMillis(),id});EventBridge.publish("context.processing.completed",id,version,new JSONObject().put("intent_id",id).put("resource_uri",uri).put("operator",op),true);}catch(Exception e){getWritableDatabase().execSQL("UPDATE intents SET state='failed',error=?,updated_at=? WHERE id=?",new Object[]{e.toString(),System.currentTimeMillis(),id});EventBridge.publish("context.processing.failed",id,version,new JSONObject().put("intent_id",id).put("resource_uri",uri).put("operator",op).put("error",e.toString()),true);}return row(id);}
 private JSONObject execute(String op,Uri uri,JSONObject p)throws Exception{if(op.equals("document.parse"))return CoreState.documents().readSource(uri.toString(),p.getString("name"),p,"context:"+p.getString("authorization_id"));if(op.equals("text.extract")){int max=Math.max(1,Math.min(1048576,p.optInt("max_bytes",262144)));try(InputStream in=context.getContentResolver().openInputStream(uri)){if(in==null)throw new FileNotFoundException(uri.toString());ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))>=0){total+=n;if(total>max)throw new IOException("Text resource exceeds limit");out.write(b,0,n);}return new JSONObject().put("kind","original_text").put("text",out.toString(StandardCharsets.UTF_8)).put("locator",new JSONObject().put("uri",uri.toString()));}}if(op.equals("video.metadata")){MediaMetadataRetriever r=new MediaMetadataRetriever();try{r.setDataSource(context,uri);return new JSONObject().put("kind","media_metadata").put("duration_ms",number(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION))).put("width",number(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH))).put("height",number(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT))).put("locator",new JSONObject().put("uri",uri.toString()));}finally{r.release();}}JSONArray caps=capabilities().getJSONArray("items");for(int i=0;i<caps.length();i++){JSONObject c=caps.getJSONObject(i);if(c.getString("id").equals(op))throw new UnsupportedOperationException(c.getString("reason"));}throw new IllegalArgumentException("Unknown processing operator");}
 private static long number(String s){try{return Long.parseLong(s);}catch(Exception e){return 0;}}private JSONObject find(String id)throws Exception{try(Cursor c=getReadableDatabase().rawQuery("SELECT * FROM intents WHERE id=?",new String[]{id})){return c.moveToFirst()?json(c):null;}}private JSONObject row(String id)throws Exception{JSONObject o=find(id);if(o==null)throw new IllegalArgumentException("Processing intent not found");return o;}private JSONObject json(Cursor c)throws Exception{JSONObject o=new JSONObject();for(int i=0;i<c.getColumnCount();i++){String k=c.getColumnName(i),v=c.getString(i);if(k.equals("result"))o.put(k,new JSONObject(v));else o.put(k,v);}return o;}
}
